      const conn = `<span class="muted">${RASHI[X.signOfHouse(h)]} · lord ${PL[l]} in the ${ORD[lh]} house${occ.length ? ` · in the house: ${occ.map((x) => PL[x]).join(", ")}` : " · house empty"}${asp.length ? ` · aspected by ${asp.map((x) => PL[x]).join(", ")}` : ""}${b != null ? ` · Ashtakavarga ${b} points` : ""}</span>`;
      const why = [];
      if (b != null) why.push(b >= 30 ? `${b} Ashtakavarga points — this house is strong within` : (b <= 24 ? `only ${b} Ashtakavarga points — this house needs support` : `${b} Ashtakavarga points — average strength`));
      why.push(`lord ${PL[l]} in ${({ ex: "its exaltation sign", own: "its own sign", fr: "a friendly sign", ne: "a neutral sign", en: "an enemy sign", deb: "its debilitation sign" })[X.dig(l)]}`);
      const ben = occ.concat(asp).filter((k) => ["Jupiter", "Venus"].includes(k)), mal = occ.concat(asp).filter((k) => ["Saturn", "Rahu", "Ketu", "Mars"].includes(k));
      if (ben.length) why.push(`good influence of ${[...new Set(ben)].map((k) => PL[k]).join("/")}`);
      if (mal.length) why.push(`${UPACHAYA.includes(h) ? "influence" : "harsh influence"} of ${[...new Set(mal)].map((k) => PL[k]).join("/")}${UPACHAYA.includes(h) ? " (in this house it gives gains through effort)" : ""}`);
