      void mh;
      const subRows = HOUSE_SUB[h].map(([name, kk]) => { const ks = X.strength(kk); let v = sc * 0.6 + (ks - 1.5) * 1.0; if (ks < 1 && v >= 1) v = 0.5; const lv = lvlOf(v); return `<tr><td>${name}</td><td><span class="lv ${lv === "good" ? "g" : (lv === "weak" ? "w" : "m")}">${SUB_TXT[lv]}</span></td><td class="muted">significator ${PL[kk]} ${X.strength(kk) >= 1.8 ? "strong" : (X.strength(kk) < 1 ? "weak" : "average")}</td></tr>`; }).join("");
